insert into research.computation(computation_key,name_fi,purpose,formula_text,interpretation_limits) values
('impact_age_structure_v1','Ikärakenne ja koko väestön työllisten osuus','Toteutunut ja vertailuvuoden ikäjakaumalla vakioitu koko väestön osuus.','R=100Σw_t r_t; C=100Σw_b r_t; rakenne=R-C; ryhmät=(w_t-w_b)(100r_t-C).','Kirjanpidollinen vakiointi, ei kausaalinen ennuste. Ikäryhmän osuus on keskitetty jakotapa. Ei virallinen työikäisten työllisyysaste.'),
('impact_production_components_v1','Tuotanto asukasta kohti: kolme tekijää','Tuottavuuden, työtuntien ja työllisten väestöosuuden laskennallinen osuus reaalituotannon muutoksesta.','GDP/person=(GDP/hour)*(hours/employed)*(employed/population). Kolmen tekijän Shapley-hajotelma keskiarvoistaa kaikki kuusi muutosjärjestystä.','Osatekijät eivät ole politiikan kausaalisia vaikutuksia. Työlliset kotimaa ja keskiväkiluku eivät vastaa työssäkäyntitilaston vuoden lopun käsitteitä. Ei yhdistetä ikärakennemalliin ilman käsitteiden harmonisointia.'),
('impact_real_income_components_v1','Kotitalouksien reaalitulo: tulo, hinnat ja väestö','Nimellisen nettotulon, hintatason ja väestömäärän osuus reaalitulon muutoksesta.','Real income/person=1000*nominal_disposable_million*(CPI2025/CPI_t)*(1/population_thousand). Shapley3 jakaa yhteisvaikutukset symmetrisesti.','Tulo ei ole mediaani tai julkisten palvelujen arvo. Nimellistulokomponentti ei yksin nimeä verotuksen, etuuksien tai palkkojen vaikutusta. Hinnat ovat yleinen elinkustannusindeksi.')
on conflict(computation_key,version_no) do nothing;
insert into research.impact_model(model_key,computation_id,engine,unit,baseline_years,outcome_definition,method_kind,approved,metadata)
select v.k,c.computation_id,v.engine,v.unit,v.baselines,v.definition,v.method,true,jsonb_build_object('version',1,'no_cross_model_sum',true,'uncertainty','Ei tilastollista epävarmuusväliä johdettu. Lähde- ja malliepävarmuus kuvattava erikseen.','theme_attribution','Teeman kytkentä ei ole teeman tunnistettu kokonaisvaikutus.')
from (values
('age_structure','impact_age_structure_v1','age_standardization','prosenttiyksikköä',array[1987,1995,2000,2010],'Työllisten osuus koko väestöstä, kaikki iät, vuoden lopun työssäkäyntitilasto.','standardization'),
('production_components','impact_production_components_v1','production_shapley3','euroa/asukas, vuoden 2015 hinnoin',array[1975,1990,2007],'BKT asukasta kohti: tuottavuus × työpanos työllistä kohti × kotimaisten työllisten suhde keskiväkilukuun.','accounting_decomposition'),
('real_income_components','impact_real_income_components_v1','income_shapley3','euroa/asukas, vuoden 2025 rahassa',array[1975,1990,2007],'Kotitalouksien reaalinen käytettävissä oleva nettotulo asukasta kohti.','accounting_decomposition')
) v(k,computation,engine,unit,baselines,definition,method) join research.computation c on c.computation_key=v.computation and c.version_no=1
on conflict(model_key) do nothing;
insert into research.impact_model_theme
select m.model_key,t.id,
case when (m.model_key='age_structure' and t.id=30) or (m.model_key='real_income_components' and t.id in (18,30)) then 'input_dimension'
when (m.model_key in ('age_structure','production_components') and t.id=15) or (m.model_key='real_income_components' and t.id=5) then 'outcome_dimension'
else 'context_unquantified' end,
case when (m.model_key='age_structure' and t.id in (15,30)) or (m.model_key='production_components' and t.id=15) or (m.model_key='real_income_components' and t.id in (5,18,30))
then 'Teema liittyy laskelman nimenomaiseen mittariin tai syötteeseen; ei koko teeman nettovaikutus.'
else 'Teema on huomioitu kontekstina. Sen erillistä vaikutusta ei tunnisteta tällä mallilla; tarvitaan mittari, vaikutuskanava, aineisto ja menetelmäarvio.' end
from research.impact_model m cross join public.atlas_themes t on conflict do nothing;
insert into research.impact_input_binding values
('age_structure','age_cells','external','employment_age_115w','FI','henkilöä'),
('production_components','gdp','public_finance','statfin15ai.v20260918.total.b1gmh.u7','FI','miljoonaa euroa'),
('production_components','hours','public_finance','statfin15ai.v20260918.total.e2.u12','FI','miljoonaa tuntia'),
('production_components','employed','public_finance','statfin15ai.v20260918.total.e1.u9','FI','tuhatta henkilöä'),
('production_components','population','public_finance','statfin15ai.v20260918.total.ep.u8','FI','tuhatta henkilöä'),
('real_income_components','nominal_income','indicator','fi.atlas1960.household_disposable_nominal','FI','miljoonaa euroa'),
('real_income_components','prices','indicator','fi.atlas1960.cost_of_living_1951','FI','indeksipisteluku'),
('real_income_components','population','public_finance','statfin15ai.v20260918.total.ep.u8','FI','tuhatta henkilöä')
on conflict do nothing;
insert into research.impact_channel(source_mechanism_id,target_mechanism_id,source_theme_id,target_theme_id,relation,rationale,evidence_status,lag_min_years,lag_max_years)
select r.source_mechanism_id,r.target_mechanism_id,s.theme_id,t.theme_id,r.relation,coalesce(r.rationale,''),coalesce(r.evidence_status,'unassessed'),t.lag_years_min,t.lag_years_max
from public.atlas_mechanism_relations r join public.atlas_mechanisms s on s.id=r.source_mechanism_id join public.atlas_mechanisms t on t.id=r.target_mechanism_id on conflict do nothing;

